// Regenerate the palette-dependent interactive fixtures using read-only pi.
// node --experimental-strip-types coding/interactive/testdata/regenerate.mjs ./pi --write
// Omit --write to check every generated byte without modifying the fixtures.
import { spawnSync } from "node:child_process";
import { readFileSync, writeFileSync } from "node:fs";
import { resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";
const here = dirname(fileURLToPath(import.meta.url));
const root = resolve(process.argv[2] ?? "./pi");
const families = [
	"auth",
	"components",
	"customeditor",
	"diff",
	"easter",
	"edittool-parity",
	"exec",
	"message",
	"modelsel",
	"selector",
	"session",
	"settings",
	"theme",
	"tree",
	"tuirenderer",
];
const write = process.argv.includes("--write");
let failed = false;
for (const family of families) {
	const result = spawnSync(process.execPath, ["--experimental-strip-types", resolve(here, `gen-${family}.mjs`), root], {
		encoding: "utf8",
		maxBuffer: 16 * 1024 * 1024,
	});
	if (result.status !== 0) throw new Error(`${family}: ${result.stderr || result.error}`);
	const target = resolve(here, `${family.replaceAll("-", "_")}_golden.txt`);
	if (write) writeFileSync(target, result.stdout);
	else if (readFileSync(target, "utf8") !== result.stdout) {
		console.error(`DIFF ${family}`);
		failed = true;
	}
}
if (failed) process.exitCode = 1;
else console.log(`${families.length} interactive golden families ${write ? "regenerated" : "byte-identical"}`);
